# ===================== نظام السجلات =====================
LOG_DIR = Path("logs")
LOG_DIR.mkdir(exist_ok=True)
logging.basicConfig(
    filename=str(LOG_DIR / "bot.log"),
    level=logging.INFO,
    format="%(asctime)s | %(levelname)s | %(message)s",
    encoding="utf-8",
)
logger = logging.getLogger("ULTRA-COLR")


def log_event(category: str, detail: str, user_id: Optional[int] = None):
    """يسجل حدثاً في ملف اللوق وفي سجل JSON بسيط (لآخر 500 حدث)."""
    try:
        logger.info(f"[{category}] uid={user_id} | {detail}")
        logs = load_json(LOGS_FILE, [])
        logs.append({
            "time": datetime.now().isoformat(),
            "category": category,
            "user_id": user_id,
            "detail": detail,
        })
        logs = logs[-500:]
        save_json(LOGS_FILE, logs)
    except Exception:
        pass


