def has_permission(user_id: int, action: str) -> bool:
    level = is_admin_level(user_id)
    if not level:
        return False
    min_role = ADMIN_ACTION_MIN_ROLE.get(action, "owner")
    return ROLE_LEVELS.get(level, 0) >= ROLE_LEVELS.get(min_role, 99)


