# ===================== نموذج بيانات الزر =====================
class ButtonInfo:
    def __init__(self, btn_type: str, text: Optional[str], callback_data: Optional[str],
                 url: Optional[str], row_index: int, col_index: int, button_index: int,
                 line_start: int, line_end: int, col_offset: int,
                 text_is_dynamic: bool, callback_is_dynamic: bool):
        self.btn_type = btn_type                # 'inline' أو 'reply'
        self.text = text if text is not None else "Dynamic"
        self.original_text = text
        self.callback_data = callback_data
        self.url = url
        self.row_index = row_index
        self.col_index = col_index
        self.button_index = button_index
        self.line_start = line_start
        self.line_end = line_end
        self.col_offset = col_offset
        self.text_is_dynamic = text_is_dynamic
        self.callback_is_dynamic = callback_is_dynamic
        # زر قابل للتعديل الآمن فقط إذا كان نصه معروفاً (Constant) وهو زر Inline
        self.is_dynamic = text_is_dynamic
        self.is_editable = (not text_is_dynamic) and btn_type == 'inline'
        self.chosen_color: Optional[str] = None
        self.chosen_emoji_id: Optional[str] = None


def _get_const_str(node) -> Optional[str]:
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    return None


class ASTButtonVisitor(ast.NodeVisitor):
    """
    يزور شجرة AST الكاملة (بما فيها الدوال، الكلاسات، الحلقات، الشروط، try/except)
    لأن generic_visit يتعمّق تلقائياً داخل كل هذه البنى. يكتشف:
    InlineKeyboardButton / KeyboardButton سواء المستدعاة مباشرة أو عبر types.*
    ويحدد إن كان الزر ديناميكياً (نصه غير حرفي/Runtime) دون اختلاق أي قيمة.
    """
    INLINE_NAMES = {'InlineKeyboardButton', 'create_emoji_btn'}
    REPLY_NAMES = {'KeyboardButton'}
    MARKUP_NAMES = {'InlineKeyboardMarkup', 'ReplyKeyboardMarkup'}

    def __init__(self):
        self.buttons: List[ButtonInfo] = []
        self.current_row_index = 0
        self.current_col_index = 0
        self.button_index = 0
        self.markup_depth = 0

    def _call_target_name(self, node: ast.Call) -> Optional[str]:
        func = node.func
        if isinstance(func, ast.Attribute):
            return func.attr
        if isinstance(func, ast.Name):
            return func.id
        return None

    def visit_Call(self, node: ast.Call):
        name = self._call_target_name(node)

        if name in self.INLINE_NAMES or name in self.REPLY_NAMES:
            btn_type = 'inline' if name in self.INLINE_NAMES else 'reply'

            text_node = None
            callback_node = None
            url_node = None

            positional = list(node.args)
            if positional:
                text_node = positional[0]
            for kw in node.keywords:
                if kw.arg == 'text' and text_node is None:
                    text_node = kw.value
                elif kw.arg == 'callback_data' or (kw.arg == 'callback' and name == 'create_emoji_btn'):
                    callback_node = kw.value
                elif kw.arg == 'url':
                    url_node = kw.value

            text_val = _get_const_str(text_node) if text_node is not None else None
            text_is_dynamic = text_node is not None and text_val is None
            # حالة عدم وجود أي نص إطلاقاً (زر بدون نص) نعتبره أيضاً غير قابل للتعديل
            if text_node is None:
                text_is_dynamic = True

            callback_val = _get_const_str(callback_node) if callback_node is not None else None
            callback_is_dynamic = callback_node is not None and callback_val is None
            callback_display = callback_val if callback_val is not None else (
                "Dynamic" if callback_is_dynamic else None)

            url_val = _get_const_str(url_node) if url_node is not None else None

            self.buttons.append(ButtonInfo(
                btn_type=btn_type,
                text=text_val,
                callback_data=callback_display,
                url=url_val,
                row_index=self.current_row_index,
                col_index=self.current_col_index,
                button_index=self.button_index,
                line_start=node.lineno - 1,
                line_end=(node.end_lineno - 1) if hasattr(node, 'end_lineno') and node.end_lineno else node.lineno - 1,
                col_offset=node.col_offset,
                text_is_dynamic=text_is_dynamic,
                callback_is_dynamic=callback_is_dynamic,
            ))
            self.current_col_index += 1
            self.button_index += 1

        self.generic_visit(node)

    def visit_List(self, node: ast.List):
        # عنصر قائمة يحتوي أزراراً => يعتبر صفاً جديداً (تقريب معقول لتقسيم الصفوف)
        has_button_call = any(
            isinstance(el, ast.Call) and self._call_target_name(el) in
            (self.INLINE_NAMES | self.REPLY_NAMES)
            for el in node.elts
        )
        if has_button_call:
            self.current_col_index = 0
            self.current_row_index += 1
        self.generic_visit(node)

    def visit_Assign(self, node: ast.Assign):
        if isinstance(node.value, ast.Call):
            name = self._call_target_name(node.value)
            if name in self.MARKUP_NAMES:
                self.current_row_index = 0
                self.current_col_index = 0
        self.generic_visit(node)

    def visit_Expr(self, node: ast.Expr):
        if isinstance(node.value, ast.Call):
            name = self._call_target_name(node.value)
            if name in ('add', 'row'):
                self.current_col_index = 0
                self.current_row_index += 1
        self.generic_visit(node)


class SmartButtonExtractor:
    """
    يتعامل مع: Inline Buttons، Reply Buttons، متغيرات، قوائم، دوال، بنى متداخلة،
    شروط، حلقات، كلاسات، وقيم ديناميكية - عبر AST Static Analysis (بدون Regex فقط).
    """
    @staticmethod
    def extract_buttons(content: str) -> Tuple[List[ButtonInfo], Optional[str]]:
        """يرجع (قائمة الأزرار، رسالة خطأ إن وجدت)."""
        try:
            tree = ast.parse(content)
        except SyntaxError as e:
            return [], f"خطأ في تحليل الملف (SyntaxError): {e}"
        except Exception as e:
            return [], f"تعذر تحليل الملف: {e}"

        visitor = ASTButtonVisitor()
        try:
            visitor.visit(tree)
        except Exception as e:
            return [], f"خطأ أثناء استخراج الأزرار: {e}"

        if len(visitor.buttons) > MAX_BUTTONS_TO_PROCESS:
            visitor.buttons = visitor.buttons[:MAX_BUTTONS_TO_PROCESS]

        return visitor.buttons, None

    @staticmethod
    def build_report(buttons: List[ButtonInfo]) -> Dict[str, int]:
        return {
            "total": len(buttons),
            "editable": sum(1 for b in buttons if b.is_editable),
            "dynamic": sum(1 for b in buttons if b.is_dynamic),
            "inline": sum(1 for b in buttons if b.btn_type == 'inline'),
            "reply": sum(1 for b in buttons if b.btn_type == 'reply'),
        }


# ===================== محرّر الكود (تعديل آمن قدر الإمكان) =====================
class CodeModifier:
    @staticmethod
    def validate_syntax(content: str) -> Tuple[bool, Optional[str]]:
        try:
            ast.parse(content)
            return True, None
        except SyntaxError as e:
            return False, str(e)
        except Exception as e:
            return False, str(e)

    @staticmethod
    def apply_changes(content: str, buttons: List[ButtonInfo]) -> str:
        lines = content.split('\n')
        line_map: Dict[int, List[ButtonInfo]] = {}
        for btn in buttons:
            if not btn.is_editable:
                continue
            if not btn.chosen_color and not btn.chosen_emoji_id:
                continue
            line_map.setdefault(btn.line_start, []).append(btn)

        for line_idx in sorted(line_map.keys(), reverse=True):
            if line_idx < 0 or line_idx >= len(lines):
                continue
            line_buttons = sorted(line_map[line_idx], key=lambda x: x.col_offset, reverse=True)
            current_line = lines[line_idx]

            for btn in line_buttons:
                cleaned_text = strip_emoji_from_text(btn.original_text) if btn.original_text else None
                if cleaned_text and cleaned_text != btn.original_text:
                    current_line = current_line.replace(f'"{btn.original_text}"', f'"{cleaned_text}"')
                    current_line = current_line.replace(f"'{btn.original_text}'", f"'{cleaned_text}'")

                current_line = re.sub(r',?\s*style\s*=\s*["\'][^"\']*["\']', '', current_line)
                current_line = re.sub(r',?\s*icon_custom_emoji_id\s*=\s*["\'][^"\']*["\']', '', current_line)

                additions = ""
                if btn.chosen_color:
                    additions += f', style="{COLOR_STYLES.get(btn.chosen_color, "primary")}"'
                if btn.chosen_emoji_id:
                    additions += f', icon_custom_emoji_id="{btn.chosen_emoji_id}"'

                paren_idx = current_line.find(')', btn.col_offset)
                if paren_idx != -1:
                    current_line = current_line[:paren_idx] + additions + current_line[paren_idx:]

            lines[line_idx] = current_line

        return '\n'.join(lines)

    @staticmethod
    def apply_random_colors(buttons: List[ButtonInfo]):
        row_colors: Dict[int, str] = {}
        for btn in buttons:
            if not btn.is_editable:
                continue
            if btn.row_index not in row_colors:
                row_colors[btn.row_index] = ROW_COLORS[btn.row_index % len(ROW_COLORS)]
            btn.chosen_color = row_colors[btn.row_index]

    @staticmethod
    def apply_changes_safe(content: str, buttons: List[ButtonInfo]) -> Tuple[str, bool, Optional[str]]:
        """
        يطبّق التعديلات ثم يتحقق من صحة الـ Syntax. إن فشل، يرجع المحتوى الأصلي
        مع رسالة خطأ بدل إرسال ملف تالف.
        """
        try:
            new_content = CodeModifier.apply_changes(content, buttons)
        except Exception as e:
            return content, False, f"فشل تطبيق التعديلات: {e}"

        ok, err = CodeModifier.validate_syntax(new_content)
        if not ok:
            return content, False, f"التعديل قد يكسر الكود (Syntax Error): {err}"
        return new_content, True, None

