TEXT_SEND_FUNCS = {
    'send_message': 'text',
    'reply_to': 'text',
    'send_photo': 'caption',
    'send_document': 'caption',
    'send_voice': 'caption',
}


class TextItem:
    def __init__(self, source_func: str, text: str, lineno: int, col_offset: int, end_col_offset: int):
        self.source_func = source_func
        self.text = text
        self.lineno = lineno              # 0-indexed
        self.col_offset = col_offset      # يشمل علامات الاقتباس
        self.end_col_offset = end_col_offset
        self.chosen_new_text: Optional[str] = None
        self.chosen_emoji: Optional[str] = None
        self.chosen_marker_text: Optional[str] = None
        self.marker_action: Optional[str] = None  # 'before' / 'after' / 'replace'

    @property
    def has_changes(self) -> bool:
        return bool(self.chosen_new_text is not None or self.chosen_emoji or self.chosen_marker_text)

    @property
    def preview_text(self) -> str:
        base = self.chosen_new_text if self.chosen_new_text is not None else self.text
        return base


class TextASTVisitor(ast.NodeVisitor):
    """
    يستخرج النصوص الظاهرة للمستخدم من استدعاءات: send_message, reply_to,
    send_photo, send_document, send_voice — سواء داخل دوال أو شروط أو حلقات
    (لأن generic_visit يتعمّق تلقائياً). لا يتعامل مع السلاسل متعددة الأسطر
    حفاظاً على سلامة أرقام الأسطر (Static Analysis آمن، بدون اختلاق قيم).
    """
    def __init__(self):
        self.items: List[TextItem] = []

    def _call_target_name(self, node: ast.Call) -> Optional[str]:
        func = node.func
        if isinstance(func, ast.Attribute):
            return func.attr
        if isinstance(func, ast.Name):
            return func.id
        return None

    def visit_Call(self, node: ast.Call):
        name = self._call_target_name(node)
        if name in TEXT_SEND_FUNCS:
            kw_name = TEXT_SEND_FUNCS[name]
            target_node = None

            for kw in node.keywords:
                if kw.arg == kw_name:
                    target_node = kw.value
                    break

            if target_node is None:
                # ابحث عن أول Constant نصي ضمن الوسائط الموضعية (تخطّي أول وسيط عادةً chat_id/message)
                for arg in node.args[1:]:
                    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                        target_node = arg
                        break

            if (target_node is not None and isinstance(target_node, ast.Constant)
                    and isinstance(target_node.value, str)):
                same_line = (getattr(target_node, 'end_lineno', target_node.lineno) == target_node.lineno)
                if same_line and hasattr(target_node, 'end_col_offset'):
                    self.items.append(TextItem(
                        source_func=name,
                        text=target_node.value,
                        lineno=target_node.lineno - 1,
                        col_offset=target_node.col_offset,
                        end_col_offset=target_node.end_col_offset,
                    ))

        self.generic_visit(node)


class TextExtractor:
    @staticmethod
    def extract_text_items(content: str) -> Tuple[List[TextItem], Optional[str]]:
        try:
            tree = ast.parse(content)
        except SyntaxError as e:
            return [], f"خطأ في تحليل الملف (SyntaxError): {e}"
        except Exception as e:
            return [], f"تعذر تحليل الملف: {e}"

        visitor = TextASTVisitor()
        try:
            visitor.visit(tree)
        except Exception as e:
            return [], f"خطأ أثناء استخراج النصوص: {e}"

        items = visitor.items
        if len(items) > MAX_BUTTONS_TO_PROCESS:
            items = items[:MAX_BUTTONS_TO_PROCESS]
        return items, None


def _quote_literal(value: str, sample: str) -> str:
    """يبني سلسلة Python صحيحة نحوياً، محافظاً على نوع علامة الاقتباس الأصلية قدر الإمكان."""
    triple = None
    for t in ('"""', "'''"):
        if sample.startswith(t):
            triple = t
            break

    value = value.replace('\r\n', '\n').replace('\n', '\\n')

    if triple:
        q = triple
        escaped = value.replace('\\', '\\\\').replace(q[0], '\\' + q[0])
        return f"{q}{escaped}{q}"

    q = sample[0] if sample and sample[0] in ('"', "'") else '"'
    escaped = value.replace('\\', '\\\\').replace(q, '\\' + q)
    return f"{q}{escaped}{q}"


class TextModifier:
    @staticmethod
    def validate_syntax(content: str) -> Tuple[bool, Optional[str]]:
        try:
            ast.parse(content)
            return True, None
        except SyntaxError as e:
            return False, str(e)
        except Exception as e:
            return False, str(e)

    @staticmethod
    def apply_changes(content: str, items: List[TextItem]) -> str:
        # ملاحظة مهمة: أرقام أعمدة AST (col_offset/end_col_offset) هي إزاحات بالبايت
        # (UTF-8) وليست إزاحات بعدد الأحرف، لذا يجب التعامل مع كل سطر كبايتات
        # عند وجود نصوص غير ASCII (كالعربية) لتفادي كسر الملف.
        settings = get_settings()
        all_presets = SEPARATOR_PRESETS + settings.get('custom_separators', [])

        lines = content.split('\n')
        line_map: Dict[int, List[TextItem]] = {}
        for item in items:
            if not item.has_changes:
                continue
            line_map.setdefault(item.lineno, []).append(item)

        for line_idx in sorted(line_map.keys(), reverse=True):
            if line_idx < 0 or line_idx >= len(lines):
                continue
            line_bytes = lines[line_idx].encode('utf-8')
            line_items = sorted(line_map[line_idx], key=lambda x: x.col_offset, reverse=True)

            for item in line_items:
                original_slice = line_bytes[item.col_offset:item.end_col_offset].decode('utf-8')
                new_value = item.chosen_new_text if item.chosen_new_text is not None else item.text

                if item.chosen_emoji:
                    new_value = f"{new_value} {item.chosen_emoji}"

                if item.chosen_marker_text and item.marker_action:
                    marker = item.chosen_marker_text
                    if item.marker_action == 'before':
                        new_value = f"{marker}\n{new_value}"
                    elif item.marker_action == 'after':
                        new_value = f"{new_value}\n{marker}"
                    elif item.marker_action == 'replace':
                        for preset in all_presets:
                            if preset in new_value:
                                new_value = new_value.replace(preset, marker)
                                break

                new_literal = _quote_literal(new_value, original_slice)
                new_literal_bytes = new_literal.encode('utf-8')
                line_bytes = line_bytes[:item.col_offset] + new_literal_bytes + line_bytes[item.end_col_offset:]

            lines[line_idx] = line_bytes.decode('utf-8')

        return '\n'.join(lines)

    @staticmethod
    def apply_changes_safe(content: str, items: List[TextItem]) -> Tuple[str, bool, Optional[str]]:
        try:
            new_content = TextModifier.apply_changes(content, items)
        except Exception as e:
            return content, False, f"فشل تطبيق تعديلات النصوص: {e}"

        ok, err = TextModifier.validate_syntax(new_content)
        if not ok:
            return content, False, f"تعديل النصوص قد يكسر الكود (Syntax Error): {err}"
        return new_content, True, None

