def button_emoji_lib_menu(btn_idx: int, page: int):
    settings = get_settings()
    per_page = settings.get('emojis_per_page', EMOJIS_PER_PAGE)
    all_emojis = get_all_emojis()
    total = len(all_emojis)
    total_pages = max(1, (total + per_page - 1) // per_page)
    page = max(0, min(page, total_pages - 1))
    start = page * per_page
    chunk = all_emojis[start:start + per_page]

    m = types.InlineKeyboardMarkup(row_width=4)
    row = []
    for i, item in enumerate(chunk):
        real_idx = start + i
        row.append(create_emoji_btn(item['emoji'], callback=f"btn_emoji_lib_pick:{btn_idx}:{real_idx}", emoji_id=item['id']))
        if len(row) == 4:
            m.row(*row)
            row = []
    if row:
        m.row(*row)

    nav = []
    if page > 0:
        nav.append(create_emoji_btn("السابق", callback=f"btn_emoji_lib:{btn_idx}:{page - 1}", emoji_id=E['arrow']))
    nav.append(create_emoji_btn(f"{page + 1}/{total_pages}", callback="noop"))
    if page < total_pages - 1:
        nav.append(create_emoji_btn("التالي", callback=f"btn_emoji_lib:{btn_idx}:{page + 1}", emoji_id=E['arrow']))
    m.row(*nav)
    m.add(create_emoji_btn("تخطي بدون إيموجي", callback=f"skip_emoji:{btn_idx}", emoji_id=E['arrow'], color="primary"))
    return m


