def check_subscription(user_id):
    settings = get_settings()
    if not settings.get('mandatory_sub_enabled', True):
        return True
    channels = settings.get('mandatory_channels', [])
    if not channels:
        return True
    for channel in channels:
        try:
            member = bot.get_chat_member(channel, user_id)
            if member.status in ['left', 'kicked']:
                return False
        except Exception:
            pass
    return True


def subscription_menu():
    settings = get_settings()
    channels = settings.get('mandatory_channels', [])
    m = types.InlineKeyboardMarkup(row_width=1)
    for i, channel in enumerate(channels, 1):
        try:
            chat = bot.get_chat(channel)
            url = f"https://t.me/{chat.username}" if chat.username else f"https://t.me/{channel}"
            m.add(types.InlineKeyboardButton(f"القناة {i}", url=url))
        except Exception:
            m.add(types.InlineKeyboardButton(f"القناة {i}", url=f"https://t.me/{channel.replace('@', '')}"))
    m.add(types.InlineKeyboardButton("تحقق من الاشتراك ✅", callback_data="check_sub"))
    return m


