@bot.message_handler(commands=['start'])
def start_cmd(message):
    uid = message.from_user.id
    username = message.from_user.username or "بدون يوزر"
    first_name = message.from_user.first_name or "مستخدم"

    settings = get_settings()
    if settings.get('maintenance_mode') and not is_any_admin(uid):
        bot.reply_to(message,
                      f"<blockquote><b>البوت في وضع الصيانة حالياً</b> <tg-emoji emoji-id='{E['warning']}'>🛠️</tg-emoji></blockquote>\n"
                      f"<blockquote>حاول مرة أخرى لاحقاً</blockquote>", parse_mode='HTML')
        return

    referrer_id = None
    if len(message.text.split()) > 1:
        ref_data = message.text.split()[1]
        if ref_data.isdigit() and int(ref_data) != uid:
            referrer_id = int(ref_data)

    is_new = add_user(uid, username, first_name, referrer_id)

    users_now = get_users()
    if users_now.get(str(uid), {}).get('is_banned'):
        bot.reply_to(message, f"<blockquote><b>تم حظرك من استخدام البوت</b> <tg-emoji emoji-id='{E['cross']}'>⛔</tg-emoji></blockquote>", parse_mode='HTML')
        return

    if not check_subscription(uid):
        sub_msg = get_settings().get('subscription_message', "عذراً، يجب عليك الاشتراك في قنوات البوت أولاً لتتمكن من استخدامه")
        text = f"<blockquote><b>{escape_html(sub_msg)}</b> <tg-emoji emoji-id='{E['warning']}'>⚠️</tg-emoji></blockquote>"
        send_with_photo(message.chat.id, text, reply_markup=subscription_menu())
        return

    if is_new:
        notify_admin(f"""
<blockquote><b>مستخدم جديد</b> <tg-emoji emoji-id='{E['fire']}'>🔥</tg-emoji></blockquote>

<blockquote><b>الاسم:</b> {first_name}
<b>اليوزر:</b> @{username}
<b>الآيدي:</b> <code>{uid}</code></blockquote>

<blockquote><b>إجمالي المستخدمين:</b> {len(users_now)}</blockquote>
""")

    clear_session(uid)

    msg = send_with_photo(message.chat.id, render_home_text(), reply_markup=main_menu())
    user_sessions[uid] = {'main_msg_id': msg.message_id}


