# ===================== استقبال إيموجي مميز نصياً (للأزرار) =====================
@bot.message_handler(func=lambda m: user_states.get(m.from_user.id) in ('asking_emoji_random', 'waiting_emoji_for_button'),
                      content_types=['text'])
def emoji_text_capture_handler(message):
    uid = message.from_user.id
    state = user_states.get(uid)
    session = user_sessions.get(uid)
    if not session or 'buttons' not in session:
        return

    current_idx = session.get('current_btn_idx', 0)
    buttons = session['buttons']
    main_msg_id = session.get('main_msg_id')

    emoji_id = None
    if message.entities:
        for ent in message.entities:
            if ent.type == 'custom_emoji':
                emoji_id = ent.custom_emoji_id
                break

    if not emoji_id:
        bot.reply_to(message,
                      f"<blockquote><b>لم أتعرف على إيموجي مميز</b> <tg-emoji emoji-id='{E['warning']}'>⚠️</tg-emoji></blockquote>",
                      parse_mode='HTML')
        return

    buttons[current_idx].chosen_emoji_id = emoji_id

    try:
        bot.delete_message(message.chat.id, message.message_id)
    except Exception:
        pass

    if not main_msg_id:
        return

    if state == 'asking_emoji_random':
        show_emoji_question_random(message.chat.id, main_msg_id, uid, session, current_idx)
    else:
        btn = buttons[current_idx]
        color = btn.chosen_color
        text = f"""
<blockquote><b>الزر {current_idx + 1} من {len(buttons)}</b> <tg-emoji emoji-id='{E['check']}'>✅</tg-emoji></blockquote>

<blockquote><b>النص:</b> {escape_html(strip_emoji_from_text(btn.text[:40]))}
<b>اللون:</b> {COLOR_EMOJI[color]} {COLOR_NAMES_AR[color]}
<b>الإيموجي:</b> تم الإضافة <tg-emoji emoji-id='{emoji_id}'>💎</tg-emoji></blockquote>
"""
        markup = types.InlineKeyboardMarkup(row_width=3)
        markup.add(create_emoji_btn(strip_emoji_from_text(btn.text[:20]) or "معاينة", callback="preview",
                                     emoji_id=emoji_id, color=COLOR_STYLES.get(color)))
        markup.add(create_emoji_btn("التالي", callback=f"next_btn:{current_idx}", emoji_id=E['arrow'], color="success"))
        edit_message(message.chat.id, main_msg_id, text, reply_markup=markup)


# ===================== إنهاء العملية وإرسال الملف =====================
def proceed_after_coloring(chat_id: int, user_id: int, session: dict):
    """يُستدعى عند انتهاء مرحلة التلوين. في الوضع المشترك ينتقل لتعديل النصوص،
    وإلا يُنهي العملية مباشرة."""
    if session.get('fileop_mode') == 'both':
        start_text_workflow(chat_id, user_id, session)
    else:
        finalize_and_send(chat_id, user_id, session)


def finalize_and_send(chat_id: int, user_id: int, session: dict):
    uid = user_id
    settings = get_settings()
    users = get_users()
    user = users.get(str(uid), {})

    buttons = session.get('buttons', [])
    text_items = session.get('text_items', [])
    content = session['content']
    filename = session['filename']

    new_content = content
    ok, err = True, None

    if buttons:
        new_content, ok, err = CodeModifier.apply_changes_safe(new_content, buttons)

    if ok and text_items:
        new_content, ok, err = TextModifier.apply_changes_safe(new_content, text_items)

    if not ok:
        edit_message(chat_id, session.get('main_msg_id'),
                      f"<blockquote><b>تعذر إتمام التعديل بأمان</b> <tg-emoji emoji-id='{E['cross']}'>❌</tg-emoji></blockquote>\n"
                      f"<blockquote><code>{escape_html(err)}</code></blockquote>\n"
                      f"<blockquote>لم يتم إرسال ملف تالف، ولم يتم خصم أي نقاط</blockquote>",
                      reply_markup=main_menu())
        increment_stats(total_failed=1)
        log_event("finish_failed", err, uid)
        clear_session(uid)
        return

    # خصم النقاط فقط بعد التأكد من نجاح التعديل (ولا تُخصم على تعديل النصوص وحده)
    if buttons and settings.get('is_paid') and not user.get('is_vip'):
        price = settings.get('coloring_price', 10)
        if user.get('points', 0) < price:
            text = (f"<blockquote><b>عذراً، رصيدك غير كافٍ</b> <tg-emoji emoji-id='{E['warning']}'>⚠️</tg-emoji></blockquote>\n\n"
                    f"<blockquote><b>سعر التلوين:</b> {price} نقطة\n<b>رصيدك الحالي:</b> {user.get('points', 0)} نقطة</blockquote>\n\n"
                    f"<blockquote>يمكنك الحصول على نقاط مجانية عن طريق دعوة أصدقائك من قسم 'حسابي'</blockquote>")
            edit_message(chat_id, session.get('main_msg_id'), text, reply_markup=main_menu())
            clear_session(uid)
            return
        users[str(uid)]['points'] -= price
        save_users(users)

    header = f"# Colored by {DEVELOPER_NAME} ({DEVELOPER_USERNAME})\n"
    final_content = header + new_content

    out_path = WORK_DIR / f"colored_{filename}"
    with open(out_path, 'w', encoding='utf-8') as f:
        f.write(final_content)

    colored = sum(1 for b in buttons if b.chosen_color)
    with_emoji = sum(1 for b in buttons if b.chosen_emoji_id)
    dynamic_count = sum(1 for b in buttons if b.is_dynamic)

    texts_found = len(text_items)
    texts_edited = sum(1 for t in text_items if t.chosen_new_text is not None)
    texts_emoji = sum(1 for t in text_items if t.chosen_emoji)
    texts_marked = sum(1 for t in text_items if t.chosen_marker_text)

    color_stats: Dict[str, int] = {}
    for btn in buttons:
        if btn.chosen_color:
            color_stats[btn.chosen_color] = color_stats.get(btn.chosen_color, 0) + 1

    color_lines = " - ".join(f"{COLOR_EMOJI[c]} {count}" for c, count in color_stats.items())
    elapsed = time.time() - session.get('start_time', time.time())

    button_block = ""
    if buttons:
        button_block = f"""
<blockquote><b>الأزرار المكتشفة:</b> {len(buttons)}
<b>الأزرار المعدلة (لون):</b> {colored}
<b>الإيموجيات المضافة للأزرار:</b> {with_emoji}
<b>العناصر الديناميكية (تم تخطيها):</b> {dynamic_count}</blockquote>

<blockquote><b>الألوان:</b> {color_lines if color_lines else 'بدون'}</blockquote>
"""

    text_block = ""
    if text_items:
        text_block = f"""
<blockquote><b>النصوص المكتشفة:</b> {texts_found}
<b>النصوص المعدلة:</b> {texts_edited}
<b>الإيموجيات المضافة للنصوص:</b> {texts_emoji}
<b>العلامات المنسقة:</b> {texts_marked}</blockquote>
"""

    report = f"""
<blockquote><b>تم الانتهاء بنجاح</b> <tg-emoji emoji-id='{E['trophy']}'>🏆</tg-emoji></blockquote>

<blockquote><b>الملف:</b> {escape_html(filename)}</blockquote>
{button_block}{text_block}
<blockquote><b>وقت المعالجة:</b> {elapsed:.1f}s</blockquote>

<blockquote>المطور: <a href="https://t.me/{get_dev_username()[1:]}">{DEVELOPER_NAME}</a></blockquote>
"""

    with open(out_path, 'rb') as f:
        bot.send_document(chat_id, f, caption=report, parse_mode='HTML')

    out_path.unlink(missing_ok=True)

    increment_stats(total_files=1, total_buttons=len(buttons), total_colored=colored,
                     total_emojis_added=with_emoji, total_texts_edited=texts_edited,
                     total_success=1, color_usage=color_stats)

    users = get_users()
    if str(uid) in users:
        users[str(uid)]['ops_count'] = users[str(uid)].get('ops_count', 0) + 1
        save_users(users)

    log_event("finish_ok", f"{filename} colored={colored} emoji={with_emoji}", uid)
    clear_session(uid)

# ===================== سير عمل تعديل النصوص =====================
def start_text_workflow(chat_id: int, uid: int, session: dict):
    settings = get_settings()
    content = session['content']

    if not settings.get('text_editing_enabled', True):
        edit_message(chat_id, session.get('main_msg_id'),
                      f"<blockquote><b>ميزة تعديل النصوص متوقفة حالياً من الأدمن</b> <tg-emoji emoji-id='{E['warning']}'>⚠️</tg-emoji></blockquote>")
        finalize_and_send(chat_id, uid, session)
        return

    text_items, err = TextExtractor.extract_text_items(content)
    if err:
        edit_message(chat_id, session.get('main_msg_id'),
                      f"<blockquote><b>تعذر تحليل النصوص</b> <tg-emoji emoji-id='{E['cross']}'>❌</tg-emoji></blockquote>\n"
                      f"<blockquote><code>{escape_html(err)}</code></blockquote>")
        log_event("text_analyze_error", err, uid)
        finalize_and_send(chat_id, uid, session)
        return

    session['text_items'] = text_items
    session['text_idx'] = 0

    if not text_items:
        edit_message(chat_id, session.get('main_msg_id'),
                      f"<blockquote><b>لم يتم العثور على نصوص قابلة للتعديل في هذا الملف</b> <tg-emoji emoji-id='{E['warning']}'>⚠️</tg-emoji></blockquote>")
        finalize_and_send(chat_id, uid, session)
        return

    user_states[uid] = 'text_editing'
    show_text_step(chat_id, session.get('main_msg_id'), uid, session, 0)


def show_text_step(chat_id: int, msg_id: int, uid: int, session: dict, idx: int):
    items = session['text_items']
    if idx >= len(items):
        finalize_and_send(chat_id, uid, session)
        return

    item = items[idx]
    session['text_idx'] = idx
    preview = escape_html(item.preview_text[:250])

    text = f"""
<blockquote><b>النص {idx + 1} من {len(items)}</b> <tg-emoji emoji-id='{E['pencil']}'>📝</tg-emoji></blockquote>

<blockquote><b>المصدر:</b> <code>{item.source_func}</code></blockquote>

<blockquote><b>النص الحالي:</b>
{preview}</blockquote>

<blockquote><b>اختر العملية:</b> <tg-emoji emoji-id='{E['arrow']}'>➡️</tg-emoji></blockquote>
"""
    edit_message(chat_id, msg_id, text, reply_markup=text_step_menu(idx))


def advance_text_step(chat_id: int, uid: int, session: dict):
    idx = session.get('text_idx', 0)
    main_msg_id = session.get('main_msg_id')
    show_text_step(chat_id, main_msg_id, uid, session, idx + 1)


@bot.callback_query_handler(func=lambda call: call.data.startswith("text_skip:"))
def text_skip_handler(call):
    uid = call.from_user.id
    if uid not in user_sessions or 'text_items' not in user_sessions[uid]:
        bot.answer_callback_query(call.id, "❌ انتهت الجلسة", show_alert=True)
        return
    advance_text_step(call.message.chat.id, uid, user_sessions[uid])
    bot.answer_callback_query(call.id)


