@bot.message_handler(func=lambda m: user_states.get(m.from_user.id) == 'waiting_custom_marker', content_types=['text'])
def custom_marker_capture_handler(message):
    uid = message.from_user.id
    session = user_sessions.get(uid)
    if not session or 'text_items' not in session:
        return

    idx = session.get('text_idx', 0)
    session.setdefault('temp_marker', {})[idx] = message.text.strip()

    try:
        bot.delete_message(message.chat.id, message.message_id)
    except Exception:
        pass

    user_states[uid] = 'text_editing'
    text = f"""
<blockquote><b>العلامة المختارة:</b> <code>{escape_html(session['temp_marker'][idx])}</code></blockquote>

<blockquote>ماذا تريد أن تفعل بها؟</blockquote>
"""
    edit_message(message.chat.id, session.get('main_msg_id'), text, reply_markup=text_marker_action_menu(idx))


@bot.callback_query_handler(func=lambda call: call.data.startswith("text_marker_action:"))
def text_marker_action_handler(call):
    uid = call.from_user.id
    _, idx, action = call.data.split(":")
    idx = int(idx)

    if uid not in user_sessions:
        bot.answer_callback_query(call.id, "❌ انتهت الجلسة", show_alert=True)
        return

    session = user_sessions[uid]
    marker = session.get('temp_marker', {}).get(idx)
    if not marker:
        bot.answer_callback_query(call.id, "❌ لم يتم اختيار علامة", show_alert=True)
        return

    session['text_items'][idx].chosen_marker_text = marker
    session['text_items'][idx].marker_action = action
    advance_text_step(call.message.chat.id, uid, session)
    bot.answer_callback_query(call.id, "تم ✅")

