@bot.callback_query_handler(func=lambda call: call.data.startswith("uadmin:"))
def user_admin_action_handler(call):
    """أزرار سريعة على بطاقة مستخدم محدد (حظر/فك حظر) من نتيجة البحث."""
    uid = call.from_user.id
    if not has_permission(uid, "ban_user"):
        _admin_deny(call)
        return

    _, action, target = call.data.split(":")
    users = get_users()
    if target not in users:
        bot.answer_callback_query(call.id, "المستخدم غير موجود ❌", show_alert=True)
        return

    if action == "ban":
        users[target]['is_banned'] = True
        save_users(users)
        log_event("user_banned", target, uid)
        bot.answer_callback_query(call.id, "تم حظر المستخدم 🚫", show_alert=True)
    elif action == "unban":
        users[target]['is_banned'] = False
        save_users(users)
        log_event("user_unbanned", target, uid)
        bot.answer_callback_query(call.id, "تم فك الحظر ✅", show_alert=True)

    render_user_card(call.message.chat.id, call.message.id, target)


def render_user_card(chat_id: int, msg_id: int, target_uid: str):
    users = get_users()
    u = users.get(target_uid)
    if not u:
        edit_message(chat_id, msg_id, "<blockquote><b>المستخدم غير موجود</b></blockquote>", reply_markup=admin_menu())
        return
    text = f"""
<blockquote><b>بطاقة المستخدم</b> <tg-emoji emoji-id='{E['people']}'>👤</tg-emoji></blockquote>

<blockquote><b>الاسم:</b> {u.get('first_name','?')}
<b>اليوزر:</b> @{u.get('username','-')}
<b>الآيدي:</b> <code>{target_uid}</code>
<b>النقاط:</b> {u.get('points',0)}
<b>الإحالات:</b> {u.get('referrals',0)}
<b>عدد العمليات:</b> {u.get('ops_count',0)}
<b>VIP:</b> {'نعم 👑' if u.get('is_vip') else 'لا'}
<b>محظور:</b> {'نعم 🚫' if u.get('is_banned') else 'لا'}
<b>آخر نشاط:</b> {u.get('last_active','-')[:19]}</blockquote>
"""
    m = types.InlineKeyboardMarkup(row_width=1)
    if u.get('is_banned'):
        m.add(create_emoji_btn("فك الحظر", callback=f"uadmin:unban:{target_uid}", emoji_id=E['check'], color="success"))
    else:
        m.add(create_emoji_btn("حظر المستخدم", callback=f"uadmin:ban:{target_uid}", emoji_id=E['cross'], color="danger"))
    m.add(create_emoji_btn("رجوع", callback="admin_panel", emoji_id=E['arrow'], color="primary"))
    edit_message(chat_id, msg_id, text, reply_markup=m)


# ===================== الإذاعة =====================
def execute_broadcast(admin_uid: int, chat_id: int, kind: str, text: Optional[str] = None,
                       photo_id: Optional[str] = None, document_file_id: Optional[str] = None,
                       caption: Optional[str] = None):
    if BROADCAST_LOCK["active"]:
        bot.send_message(chat_id, "⚠️ هناك إذاعة أخرى قيد التنفيذ حالياً، حاول لاحقاً")
        return

    BROADCAST_LOCK["active"] = True
    try:
        users = get_users()
        success, failed = 0, 0
        for target_id in users.keys():
            try:
                if kind == 'text':
                    bot.send_message(int(target_id), text, parse_mode='HTML')
                elif kind == 'photo':
                    bot.send_photo(int(target_id), photo_id, caption=caption or "", parse_mode='HTML')
                elif kind == 'document':
                    bot.send_document(int(target_id), document_file_id, caption=caption or "", parse_mode='HTML')
                success += 1
            except Exception:
                failed += 1
        bot.send_message(chat_id,
                          f"<blockquote><b>تم الإرسال إلى {success} مستخدم</b> <tg-emoji emoji-id='{E['check']}'>✅</tg-emoji></blockquote>\n"
                          f"<blockquote>فشل الإرسال إلى {failed} مستخدم</blockquote>", parse_mode='HTML')
        log_event("broadcast", f"kind={kind} success={success} failed={failed}", admin_uid)
    finally:
        BROADCAST_LOCK["active"] = False
        user_states[admin_uid] = None


@bot.message_handler(content_types=['photo'])
def photo_handler(message):
    uid = message.from_user.id
    state = user_states.get(uid)

    if state == 'admin_waiting_broadcast' and is_any_admin(uid):
        execute_broadcast(uid, message.chat.id, kind='photo',
                           photo_id=message.photo[-1].file_id, caption=message.caption)
        return

    if state == 'admin_waiting_photo' and is_any_admin(uid):
        photo_id = message.photo[-1].file_id
        settings = get_settings()
        settings['welcome_photo'] = photo_id
        save_settings(settings)
        bot.reply_to(message, f"<blockquote><b>تم تعيين الصورة بنجاح</b> <tg-emoji emoji-id='{E['check']}'>✅</tg-emoji></blockquote>", parse_mode='HTML')
        user_states[uid] = None


def handle_restore_upload(message):
    uid = message.from_user.id
    try:
        file_info = bot.get_file(message.document.file_id)
        downloaded = bot.download_file(file_info.file_path)
        data = json.loads(downloaded.decode('utf-8'))

        if data.get('format') != 'ultra_colr_backup_v1' or 'users' not in data or 'settings' not in data:
            bot.reply_to(message, "<blockquote><b>ملف غير صالح كنسخة احتياطية ❌</b></blockquote>", parse_mode='HTML')
            return

        save_users(data['users'])
        save_settings(data['settings'])
        if 'stats' in data:
            save_stats(data['stats'])

        bot.reply_to(message, "<blockquote><b>تمت الاستعادة بنجاح ✅</b></blockquote>", parse_mode='HTML')
        log_event("restore", "manual restore", uid)
    except Exception as e:
        bot.reply_to(message, f"<blockquote><b>فشلت الاستعادة</b></blockquote>\n<blockquote><code>{escape_html(str(e))}</code></blockquote>", parse_mode='HTML')
        log_event("restore_failed", str(e), uid)
    finally:
        user_states[uid] = None


# ===================== استقبال إيموجي مخصص لمكتبة الأدمن =====================
@bot.message_handler(func=lambda m: user_states.get(m.from_user.id) == 'admin_waiting_custom_emoji', content_types=['text'])
def custom_emoji_capture_handler(message):
    uid = message.from_user.id
    emoji_id = None
    glyph = "✨"
    if message.entities:
        for ent in message.entities:
            if ent.type == 'custom_emoji':
                emoji_id = ent.custom_emoji_id
                glyph = message.text[ent.offset:ent.offset + ent.length] if message.text else "✨"
                break

    if not emoji_id:
        bot.reply_to(message, "<blockquote><b>لم أتعرف على إيموجي مخصص في رسالتك ❌</b></blockquote>", parse_mode='HTML')
        return

    settings = get_settings()
    custom = settings.get('custom_emojis', [])
    custom.append({"id": emoji_id, "emoji": glyph, "name": f"custom_{len(custom)+1}"})
    settings['custom_emojis'] = custom
    save_settings(settings)
    log_event("emoji_added", emoji_id, uid)
    bot.reply_to(message, "<blockquote><b>تمت إضافة الإيموجي للمكتبة بنجاح ✅</b></blockquote>", parse_mode='HTML')
    user_states[uid] = None


