@bot.message_handler(func=lambda m: True, content_types=['text'])
def text_handler(message):
    uid = message.from_user.id
    state = user_states.get(uid)

    if not state:
        return

    if state.startswith('admin_') and not is_any_admin(uid):
        return

    if state == 'admin_waiting_broadcast':
        execute_broadcast(uid, message.chat.id, kind='text', text=message.text)
        return

    elif state == 'admin_waiting_welcome':
        settings = get_settings()
        settings['welcome_text'] = message.text
        save_settings(settings)
        bot.reply_to(message, "<blockquote><b>تم تحديث رسالة الترحيب بنجاح ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return

    elif state == 'admin_waiting_sub_message':
        settings = get_settings()
        settings['subscription_message'] = message.text
        save_settings(settings)
        bot.reply_to(message, "<blockquote><b>تم تحديث رسالة الاشتراك بنجاح ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return

    elif state == 'admin_waiting_dev_link':
        settings = get_settings()
        val = message.text.strip()
        settings['developer_username'] = val if val.startswith('@') else f"@{val}"
        save_settings(settings)
        bot.reply_to(message, "<blockquote><b>تم تحديث يوزر المطور ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return

    elif state == 'admin_waiting_channel_link':
        settings = get_settings()
        val = message.text.strip()
        settings['channel_username'] = val if val.startswith('@') else f"@{val}"
        save_settings(settings)
        bot.reply_to(message, "<blockquote><b>تم تحديث يوزر القناة ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return

    elif state == 'admin_waiting_ref_points':
        if message.text.isdigit():
            settings = get_settings()
            settings['referral_points'] = int(message.text)
            save_settings(settings)
            bot.reply_to(message, f"<blockquote><b>تم تحديث نقاط الإحالة إلى {message.text} ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>يرجى إرسال رقم صحيح ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_color_price':
        if message.text.isdigit():
            settings = get_settings()
            settings['coloring_price'] = int(message.text)
            save_settings(settings)
            bot.reply_to(message, f"<blockquote><b>تم تحديث سعر التلوين إلى {message.text} ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>يرجى إرسال رقم صحيح ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_emojis_per_page':
        if message.text.isdigit() and 4 <= int(message.text) <= 20:
            settings = get_settings()
            settings['emojis_per_page'] = int(message.text)
            save_settings(settings)
            bot.reply_to(message, f"<blockquote><b>تم التحديث إلى {message.text} ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>أرسل رقماً بين 4 و20 ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_max_text_len':
        if message.text.isdigit() and int(message.text) > 0:
            settings = get_settings()
            settings['max_text_length'] = int(message.text)
            save_settings(settings)
            bot.reply_to(message, f"<blockquote><b>تم التحديث إلى {message.text} حرف ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>أرسل رقماً صحيحاً أكبر من صفر ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_add_preset':
        settings = get_settings()
        presets = settings.get('custom_separators', [])
        presets.append(message.text.strip())
        settings['custom_separators'] = presets
        save_settings(settings)
        bot.reply_to(message, "<blockquote><b>تمت إضافة العلامة بنجاح ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return

    elif state == 'admin_waiting_vip':
        users = get_users()
        target_uid = message.text.strip()
        if target_uid in users:
            users[target_uid]['is_vip'] = not users[target_uid].get('is_vip', False)
            save_users(users)
            status = "ترقية" if users[target_uid]['is_vip'] else "تنزيل"
            log_event("vip_change", f"{target_uid} -> {status}", uid)
            bot.reply_to(message, f"<blockquote><b>تم {status} المستخدم بنجاح ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>المستخدم غير موجود في قاعدة البيانات ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_points_uid':
        users = get_users()
        target_uid = message.text.strip()
        if target_uid in users:
            user_sessions.setdefault(uid, {})['target_points_uid'] = target_uid
            user_states[uid] = 'admin_waiting_points_amount'
            bot.reply_to(message, "<blockquote><b>أرسل عدد النقاط المراد إضافتها (سالب للخصم)</b></blockquote>", parse_mode='HTML')
        else:
            bot.reply_to(message, "<blockquote><b>المستخدم غير موجود ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_points_amount':
        text_val = message.text.strip()
        is_valid = text_val.lstrip('-').isdigit()
        if is_valid:
            target_uid = user_sessions.get(uid, {}).get('target_points_uid')
            amount = int(text_val)
            users = get_users()
            if target_uid in users:
                users[target_uid]['points'] = users[target_uid].get('points', 0) + amount
                save_users(users)
                log_event("points_change", f"{target_uid} {amount:+d}", uid)
                bot.reply_to(message, f"<blockquote><b>تم تحديث نقاط المستخدم بمقدار {amount} بنجاح ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
            user_sessions.pop(uid, None)
        else:
            bot.reply_to(message, "<blockquote><b>يرجى إرسال رقم صحيح ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_channel':
        settings = get_settings()
        channels = settings.get('mandatory_channels', [])
        if message.text not in channels:
            channels.append(message.text)
            settings['mandatory_channels'] = channels
            save_settings(settings)
            bot.reply_to(message, "<blockquote><b>تم إضافة القناة بنجاح ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>القناة موجودة مسبقاً ⚠️</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_del_channel':
        settings = get_settings()
        channels = settings.get('mandatory_channels', [])
        if message.text in channels:
            channels.remove(message.text)
            settings['mandatory_channels'] = channels
            save_settings(settings)
            bot.reply_to(message, "<blockquote><b>تم حذف القناة بنجاح ✅</b></blockquote>", parse_mode='HTML')
            user_states[uid] = None
        else:
            bot.reply_to(message, "<blockquote><b>القناة غير موجودة ❌</b></blockquote>", parse_mode='HTML')
        return

    elif state == 'admin_waiting_search_user':
        target_uid = message.text.strip()
        if not target_uid.isdigit():
            bot.reply_to(message, "<blockquote><b>أرسل آيدي رقمي صحيح ❌</b></blockquote>", parse_mode='HTML')
            return
        users = get_users()
        if target_uid not in users:
            bot.reply_to(message, "<blockquote><b>لم يتم العثور على هذا المستخدم ❌</b></blockquote>", parse_mode='HTML')
            return
        user_states[uid] = None
        msg = bot.send_message(message.chat.id, "⏳")
        render_user_card(message.chat.id, msg.message_id, target_uid)
        return

    elif state == 'admin_waiting_add_admin':
        parts = message.text.strip().split()
        if len(parts) != 2 or not parts[0].isdigit() or parts[1] not in ('admin', 'moderator', 'support'):
            bot.reply_to(message, "<blockquote><b>صيغة غير صحيحة، مثال: 123456789 moderator ❌</b></blockquote>", parse_mode='HTML')
            return
        new_id, role = int(parts[0]), parts[1]
        settings = get_settings()
        admins = settings.get('admins', [])
        admins = [a for a in admins if a['id'] != new_id]
        admins.append({"id": new_id, "role": role})
        settings['admins'] = admins
        save_settings(settings)
        log_event("admin_added", f"{new_id} ({role})", uid)
        bot.reply_to(message, f"<blockquote><b>تمت إضافة المشرف {new_id} برتبة {role} بنجاح ✅</b></blockquote>", parse_mode='HTML')
        user_states[uid] = None
        return


# ===================== تشغيل البوت =====================
if __name__ == "__main__":
    print("🚀 البوت يعمل الآن...")
    log_event("startup", "bot started")
    try:
        bot.infinity_polling(skip_pending=True)
    except Exception:
        logger.error(f"Fatal polling error: {traceback.format_exc()}")
